// EN: Validate and prepare input data
// DE: Eingabedaten validieren und vorbereiten

const item = $input.item.json;

// Required fields check / Pflichtfelder prüfen
const requiredFields = ['eventTitle', 'eventDate', 'venue', 'city'];
const missingFields = requiredFields.filter(field => !item[field]);

if (missingFields.length > 0) {
  throw new Error(`Missing required fields: ${missingFields.join(', ')}`);
}

// Set defaults / Standardwerte setzen
const publishTo = item.publishTo || {
  twitter: true,
  instagram: true,
  facebook: true,
  linkedin: false,
  reddit: false,
  email: false
};

// Format date / Datum formatieren
let formattedDate = item.eventDate;
if (item.eventDate && item.eventTime) {
  const date = new Date(`${item.eventDate}T${item.eventTime}`);
  formattedDate = date.toLocaleDateString('de-DE', { 
    weekday: 'long', 
    year: 'numeric', 
    month: 'long', 
    day: 'numeric' 
  });
}

// Prepare output / Ausgabe vorbereiten
return [{
  json: {
    eventTitle: item.eventTitle,
    eventDate: item.eventDate,
    eventTime: item.eventTime || '22:00',
    formattedDate: formattedDate,
    venue: item.venue,
    city: item.city,
    description: item.description || '',
    imageUrl: item.imageUrl || '',
    ticketUrl: item.ticketUrl || '',
    publishTo: publishTo,
    emailRecipients: item.emailRecipients || [],
    // Reddit-specific fields / Reddit-spezifische Felder
    redditSubreddit: item.redditSubreddit || '',
    redditFlair: item.redditFlair || '',
    redditNsfw: item.redditNsfw || false,
    redditSpoiler: item.redditSpoiler || false,
    redditPostType: item.redditPostType || 'text', // 'text' or 'link'
    timestamp: new Date().toISOString()
  }
}];

// EN: Format content for different platforms
// DE: Content für verschiedene Plattformen formatieren

const item = $input.item.json;

// Base text / Basistext
const baseText = `${item.eventTitle}

📅 ${item.formattedDate}
🕐 ${item.eventTime}
📍 ${item.venue}, ${item.city}

${item.description || ''}`.trim();

// Twitter/X format (280 chars max) / Twitter/X Format (max. 280 Zeichen)
let twitterText = baseText;
if (item.ticketUrl) {
  twitterText += `

🎫 Tickets: ${item.ticketUrl}`;
}
// Truncate if too long / Kürzen falls zu lang
if (twitterText.length > 280) {
  twitterText = twitterText.substring(0, 277) + '...';
}

// Instagram format (2200 chars max, supports emojis) / Instagram Format (max. 2200 Zeichen)
let instagramText = `${item.eventTitle}

📅 ${item.formattedDate}
🕐 ${item.eventTime}
📍 ${item.venue}, ${item.city}

${item.description || ''}`;
if (item.ticketUrl) {
  instagramText += `

🎫 Link in Bio oder: ${item.ticketUrl}`;
}
instagramText += `

#DJ #Event #${item.city.replace(/\s/g, '')} #Nightlife`;

// Facebook format / Facebook Format
let facebookText = `${item.eventTitle}

📅 ${item.formattedDate}
🕐 ${item.eventTime}
📍 ${item.venue}, ${item.city}

${item.description || ''}`;
if (item.ticketUrl) {
  facebookText += `

🎫 Tickets: ${item.ticketUrl}`;
}

// LinkedIn format (professional tone) / LinkedIn Format (professioneller Ton)
let linkedinText = `🎧 ${item.eventTitle}

📅 Date: ${item.formattedDate}
🕐 Time: ${item.eventTime}
📍 Location: ${item.venue}, ${item.city}

${item.description || 'Join us for an amazing night!'}`;
if (item.ticketUrl) {
  linkedinText += `

🎫 Get your tickets: ${item.ticketUrl}`;
}

// Reddit format (Markdown supported) / Reddit Format (Markdown unterstützt)
let redditText = `# ${item.eventTitle}

**📅 Date:** ${item.formattedDate}
**🕐 Time:** ${item.eventTime}
**📍 Location:** ${item.venue}, ${item.city}

${item.description || ''}

---

**Event Details:**
- **Venue:** ${item.venue}
- **City:** ${item.city}
- **Date:** ${item.formattedDate}
- **Time:** ${item.eventTime}`;

if (item.ticketUrl) {
  redditText += `

**🎫 [Get Tickets](${item.ticketUrl})**`;
}

if (item.imageUrl) {
  redditText += `

![Event Image](${item.imageUrl})`;
}

redditText += `

---

*Posted by automated system*`;

// Email format (HTML) / E-Mail Format (HTML)
const emailHtml = `
  <h2>${item.eventTitle}</h2>
  <p><strong>📅 Date:</strong> ${item.formattedDate}</p>
  <p><strong>🕐 Time:</strong> ${item.eventTime}</p>
  <p><strong>📍 Location:</strong> ${item.venue}, ${item.city}</p>
  ${item.description ? `<p>${item.description}</p>` : ''}
  ${item.ticketUrl ? `<p><a href="${item.ticketUrl}" style="background-color: #4CAF50; color: white; padding: 10px 20px; text-decoration: none; border-radius: 5px;">🎫 Get Tickets</a></p>` : ''}
`;

const emailText = `${item.eventTitle}

Date: ${item.formattedDate}
Time: ${item.eventTime}
Location: ${item.venue}, ${item.city}

${item.description || ''}

${item.ticketUrl ? `Tickets: ${item.ticketUrl}` : ''}`;

return [{
  json: {
    ...item,
    twitterText: twitterText,
    instagramText: instagramText,
    facebookText: facebookText,
    linkedinText: linkedinText,
    redditText: redditText,
    emailHtml: emailHtml,
    emailText: emailText
  }
}];

// EN: Collect results from all posting operations
// DE: Sammelt Ergebnisse aller Posting-Operationen

const results = [];
const allItems = $input.all();

// Get original event data from first item / Hole ursprüngliche Event-Daten vom ersten Item
const inputData = allItems[0]?.json || {};

// Platform detection from data / Plattform-Erkennung aus Daten
const detectPlatform = (item) => {
  // Check for platform-specific fields / Prüfe plattform-spezifische Felder
  if (item.id_str || item.id) return 'Twitter/X';
  if (item.instagram_id || item.media_id) return 'Instagram';
  if (item.post_id || item.facebook_id) return 'Facebook';
  if (item.linkedin_id || item.urn) return 'LinkedIn';
  if (item.messageId || item.emailId) return 'Email';
  if (item.name && item.name.startsWith('t3_')) return 'Reddit';
  // Fallback: check for error or success indicators / Fallback: Prüfe Fehler- oder Erfolgs-Indikatoren
  if (item.error) return 'Unknown Platform';
  return 'Unknown Platform';
};

// Collect all outputs / Alle Ausgaben sammeln
allItems.forEach((item) => {
  const platform = detectPlatform(item.json);
  const hasError = item.json.error || item.json.errorMessage || false;

  results.push({
    platform: platform,
    success: !hasError,
    data: item.json,
    timestamp: new Date().toISOString()
  });
});

// If no results collected, create summary from input / Falls keine Ergebnisse gesammelt, erstelle Zusammenfassung aus Eingabe
if (results.length === 0 && inputData.eventTitle) {
  results.push({
    platform: 'No platforms enabled',
    success: true,
    data: { message: 'No platforms were enabled for posting' },
    timestamp: new Date().toISOString()
  });
}

return [{
  json: {
    eventTitle: inputData.eventTitle || 'Unknown Event',
    eventDate: inputData.eventDate || '',
    timestamp: new Date().toISOString(),
    results: results,
    summary: {
      total: results.length,
      successful: results.filter(r => r.success).length,
      failed: results.filter(r => !r.success).length
    }
  }
}];
